<?php

namespace App\Entity;

use Doctrine\ORM\Mapping as ORM;

#[ORM\Entity(repositoryClass: \App\Repository\ProductTagTranslationRepository::class)]
class ProductTagTranslation
{
    /** Typed by the owner in the admin (only ever the restaurant's default language). */
    public const SOURCE_HUMAN  = 'human';
    /** Generated by AiTagTranslator. */
    public const SOURCE_AI     = 'ai';
    /** From config/preset_tags.yaml (DefaultTagSeeder / app:tags:resync-preset-translations). */
    public const SOURCE_PRESET = 'preset';

    #[ORM\Id]
    #[ORM\GeneratedValue]
    #[ORM\Column]
    private ?int $id = null;

    #[ORM\ManyToOne(
        targetEntity: ProductTag::class,
        inversedBy: 'translations'
    )]
    #[ORM\JoinColumn(nullable: false)]
    private ProductTag $tag;

    #[ORM\Column(length: 5)]
    private string $locale;

    public function getId(): ?int
    {
        return $this->id;
    }

    public function getTag(): ProductTag
    {
        return $this->tag;
    }

    public function setTag(ProductTag $tag): void
    {
        $this->tag = $tag;
    }

    #[ORM\Column(length: 100)]
    private string $name;

    // Renaming a tag drops its 'ai' and 'preset' rows (TagsController::edit)
    // so they're regenerated from the new name; 'human' rows stay.
    #[ORM\Column(length: 10, options: ['default' => self::SOURCE_HUMAN])]
    private string $source = self::SOURCE_HUMAN;

    public function getLocale(): string
    {
        return $this->locale;
    }

    public function setLocale(string $locale): void
    {
        $this->locale = $locale;
    }

    public function getName(): string
    {
        return $this->name;
    }

    public function setName(string $name): void
    {
        $this->name = $name;
    }

    public function getSource(): string
    {
        return $this->source;
    }

    public function setSource(string $source): void
    {
        $this->source = $source;
    }
}
